/**
 * The types `data/currency/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CurrencyName, CurrencyDefinition, CurrencyFlowRow, CashEnemyValueRule, EliteCellTierRow
 * depends    —
 * used by    src/data/currency/data, src/data/currency/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from data.ts

export type CurrencyName =
  | 'Cash'
  | 'Coins'
  | 'Gems'
  | 'Power Stones'
  | 'Medals'
  | 'Elite Cells'
  | 'Keys'
  | 'Bits'
  | 'Tokens'
  | 'Module Currency'

export interface CurrencyDefinition {
  name: CurrencyName
  summary: string
  persistence: 'run-only' | 'account' | 'mixed'
}

export interface CurrencyFlowRow {
  name: CurrencyName
  acquisitionSources: readonly string[]
  spendUses: readonly string[]
}

export interface CashEnemyValueRule {
  startWave: number
  endWaveInclusive: number | null
  waveStep: number
  cashIncreasePerStep: number
}

export interface EliteCellTierRow {
  tier: number
  minimumCells: number
  maximumCells: number
  averageCells: number
  averageIncreaseFromPriorPercent: number | null
}
